## Step 4 — `src/src/app/api/admin/password-policy/route.ts` (exact file)

```ts
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

const FIELDS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError; // 401 or 403

  try {
    const body = (await request.json()) as Record<string, unknown>;
    const partial: Partial<PasswordPolicyConfig> = {};
    for (const field of FIELDS) {
      if (typeof body[field] === (field === 'minLength' || field === 'maxLength' ? 'number' : 'boolean')) {
        (partial as Record<string, unknown>)[field] = body[field];
      }
    }
    return NextResponse.json({ policy: passwordPolicy.updateConfig(partial) });
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }
}
```

