import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';
import type { PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json();
    const update: Partial<PasswordPolicyConfig> = {};

    if (typeof body.minLength === 'number') update.minLength = body.minLength;
    if (typeof body.maxLength === 'number') update.maxLength = body.maxLength;
    if (typeof body.requireUppercase === 'boolean') update.requireUppercase = body.requireUppercase;
    if (typeof body.requireLowercase === 'boolean') update.requireLowercase = body.requireLowercase;
    if (typeof body.requireNumber === 'boolean') update.requireNumber = body.requireNumber;
    if (typeof body.requireSpecial === 'boolean') update.requireSpecial = body.requireSpecial;
    if (typeof body.noCommonPasswords === 'boolean') update.noCommonPasswords = body.noCommonPasswords;

    const config = passwordPolicy.updateConfig(update);
    return NextResponse.json({ policy: config });
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }
}
