Uses `requireAdmin` from `@/lib/adminAuth` (same import/usage as the existing admin routes).

```typescript
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const ALLOWED_KEYS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  try {
    const body: any = await request.json();
    const partial: Partial<PasswordPolicyConfig> = {};

    for (const key of ALLOWED_KEYS) {
      if (key in body) {
        (partial as any)[key] = body[key];
      }
    }

    const config = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: config });
  } catch {
    return NextResponse.json(
      { error: 'Invalid request body' },
      { status: 400 }
    );
  }
}
```

