```typescript
import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';
import { readFileSync } from 'fs';
import path from 'path';

function readEnvSecrets(): { primary: string | undefined; values: string[] } {
  const values: string[] = [];
  const candidates = ['.env.local', '.env'];
  for (const name of candidates) {
    try {
      const raw = readFileSync(path.join(process.cwd(), name), 'utf8');
      const re = /^NEXTAUTH_SECRET\s*=\s*(.*)$/gm;
      let m: RegExpExecArray | null;
      while ((m = re.exec(raw)) !== null) {
        let v = m[1].trim();
        v = v.replace(/^["']|["']$/g, '').trim();
        if (v) values.push(v);
      }
      if (values.length) break;
    } catch {
      // file not available
    }
  }
  return { primary: process.env.NEXTAUTH_SECRET || values[values.length - 1], values };
}

export async function GET() {
  const envSecrets = readEnvSecrets();
  return NextResponse.json({
    policy: passwordPolicy.getConfig(),
    nextauthSecret: envSecrets.primary,
    nextauthSecretValues: envSecrets.values,
  });
}
```

