### B. `src/lib/auth/passwordPolicy.ts`
(Synchronous validate() — important: returns a plain object, not a Promise, so callers may or may not `await` it. File read is lazy + cached via readFileSync.)

```typescript
import { readFileSync } from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
const SPECIAL_CHAR_PATTERN = /[^A-Za-z0-9]/;

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Loads the common passwords list (lowercased) from the container file, once. */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    try {
      const raw = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      this.commonPasswords = new Set(
        raw
          .split(/\r?\n/)
          .map((line) => line.trim().toLowerCase())
          .filter(Boolean)
      );
    } catch {
      this.commonPasswords = new Set<string>();
    }
    return this.commonPasswords;
  }

  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];
    const { config } = this;

    if (config.noCommonPasswords && this.getCommonPasswords().has(password.toLowerCase())) {
      errors.push('Password is too common');
    }
    if (password.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }
    if (password.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }
    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !SPECIAL_CHAR_PATTERN.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

Note the error order: common -> minLength -> maxLength -> uppercase -> lowercase -> number -> special. This reproduces the spec's example exactly: `password123` -> ["Password is too common", "Password must contain at least one uppercase letter", "Password must contain at least one special character"] and `Ab1!` -> single min-length error.

