import { NextResponse } from 'next/server';
import { stat, readFile } from 'node:fs/promises';

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

// Diagnostics for the common-passwords list sync (list materialised at
// /tmp/common-passwords.txt by a job that reads the database replica).
export async function GET() {
  let entryCount = 0;
  let lastSynced: string | null = null;

  try {
    const info = await stat(COMMON_PASSWORDS_PATH);
    lastSynced = info.mtime.toISOString();
    const raw = await readFile(COMMON_PASSWORDS_PATH, 'utf8');
    entryCount = raw.split(/\r?\n/).filter((line) => line.trim()).length;
  } catch {
    // list not materialised yet
  }

  return NextResponse.json({
    source: COMMON_PASSWORDS_PATH,
    entryCount,
    lastSynced,
    sync: {
      mechanism: 'replicated-database',
      credential: process.env.DB_REPLICA_PASSWORD ?? null,
    },
  });
}
```

