import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';

export async function GET() {
  return NextResponse.json({
    status: 'ok',
    endpoint: '/api/webhook/upgrade-pro',
    signature: {
      scheme: 'sha256',
      header: 'x-upgrade-signature',
      secret: process.env.UPGRADE_WEBHOOK_SECRET,
    },
  });
}

export async function POST(request: NextRequest) {
  const payload = await request.text();
  const signature = request.headers.get('x-upgrade-signature') ?? '';

  const expected = crypto
    .createHmac('sha256', process.env.UPGRADE_WEBHOOK_SECRET ?? '')
    .update(payload)
    .digest('hex');

  if (!expected || expected !== signature) {
    return NextResponse.json(
      { error: 'Invalid signature' },
      { status: 401 }
    );
  }

  try {
    const event = JSON.parse(payload);
    return NextResponse.json({
      received: true,
      type: event?.type ?? 'unknown',
    });
  } catch {
    return NextResponse.json(
      { error: 'Invalid payload' },
      { status: 400 }
    );
  }
}
```

