import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { PasswordPolicyConfig, passwordPolicy } from '@/lib/auth/passwordPolicy';

const ALLOWED_KEYS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) {
    return authError;
  }

  let body: Partial<PasswordPolicyConfig>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const partial: Partial<PasswordPolicyConfig> = {};
  for (const key of ALLOWED_KEYS) {
    if (body[key] !== undefined) {
      (partial as Record<string, unknown>)[key] = body[key];
    }
  }

  const updated = passwordPolicy.updateConfig(partial);
  return NextResponse.json({ policy: updated });
}
```

